const CODE_LINE_RE = /^(?:export\s+(?:function|const|class)\s+([A-Za-z_$][\w$]*)|function\s+([A-Za-z_$][\w$]*)|const\s+([A-Za-z_$][\w$]*)\s*=)/
const PY_LINE_RE = /^(?:def|class)\s+([A-Za-z_$][\w$]*)/

export function outlineOf (text, path) {
  const str = String(text == null ? '' : text)
  const ext = (path.match(/\.([^.\/]+)$/) || [])[1]
  const out = []
  if (ext === 'mjs' || ext === 'js' || ext === 'ts') {
    for (const line of str.split('\n')) {
      const indentMatch = /^( *)/.exec(line)
      const indent = indentMatch[1].length
      if (indent !== 0 && indent !== 2) continue
      const rest = line.slice(indent)
      const m = CODE_LINE_RE.exec(rest)
      if (m) out.push({ name: m[1] || m[2] || m[3], kind: 'code' })
    }
  } else if (ext === 'py') {
    for (const line of str.split('\n')) {
      if (/^\s/.test(line)) continue
      const m = PY_LINE_RE.exec(line)
      if (m) out.push({ name: m[1], kind: 'code' })
    }
  } else if (ext === 'md') {
    for (const line of str.split('\n')) {
      const m = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line)
      if (m) out.push({ name: m[2], kind: 'heading' })
    }
  } else if (ext === 'json') {
    try {
      const obj = JSON.parse(str)
      if (obj && typeof obj === 'object' && !Array.isArray(obj)) {
        for (const k of Object.keys(obj)) out.push({ name: k, kind: 'key' })
      }
    } catch {
      // not JSON
    }
  }
  return out.slice(0, 200)
}

const markerBlockOf = (body, marker) => {
  const lines = String(body == null ? '' : body).split('\n')
  const i = lines.findIndex((l) => l.startsWith(marker))
  if (i === -1) return ''
  const out = [lines[i].slice(marker.length).replace(/^[ \t]+/, '')]
  for (let j = i + 1; j < lines.length && lines[j].trim() !== ''; j++) out.push(lines[j])
  return out.join('\n')
}

function backtickSpans (body) {
  return [...String(body == null ? '' : body).matchAll(/`([^`]*)`/g)].map((m) => m[1])
}

function hitsOf (body, outline) {
  const spans = backtickSpans(body)
  const names = []
  for (const { name } of outline) {
    if (spans.some((s) => wholeWordMatch(s, name))) names.push(name)
  }
  return names
}

function taskById (tasks, id) {
  return tasks.find((t) => String(t.id) === String(id))
}

function personOf (task, withLegs) {
  const out = {
    id: task.id,
    title: task.title,
    claim: markerBlockOf(task.body, '**Claim:**'),
    machine: task.clauses || [],
    interfaces: task.interfaces,
    files: task.files || [],
    context: markerBlockOf(task.body, '**Context:**'),
  }
  if (withLegs) out.legs = markerBlockOf(task.body, '- Legs:')
  return out
}

function producesBulletFor (body, symbol) {
  const lines = String(body == null ? '' : body).split('\n')
  for (const line of lines) {
    const t = line.trim()
    if (t.startsWith('- Produces:') && wholeWordMatch(t, symbol)) return t
  }
  return null
}

export async function pairState ({ pair, tasks, read }) {
  const producerId = pair.producer != null ? pair.producer : pair.a
  const consumerId = pair.consumer != null ? pair.consumer : pair.b
  const producerTask = taskById(tasks, producerId)
  const consumerTask = taskById(tasks, consumerId)

  const producer = personOf(producerTask, false)
  const consumer = personOf(consumerTask, true)

  const shared = []
  for (const p of (pair.paths || [])) {
    const baseText = await read(p)
    const exists = !!baseText
    const outline = outlineOf(baseText, p)
    shared.push({
      path: p,
      exists_at_base: exists,
      outline,
      producer_hits: hitsOf(producerTask.body, outline),
      consumer_hits: hitsOf(consumerTask.body, outline),
    })
  }

  let stated = false
  if (pair.symbol) {
    const bullet = producesBulletFor(producerTask.body, pair.symbol)
    if (bullet && String(consumerTask.body).includes(bullet)) stated = true
  }
  const shape = { symbol: pair.symbol || null, stated_in_consumer: stated }

  const state = { producer, consumer, shared, shape }
  let bytes = Buffer.byteLength(JSON.stringify(state), 'utf8')
  while (bytes > 60000) {
    let cutAny = false
    for (const s of state.shared) {
      if (s.outline.length > 0) {
        s.outline = s.outline.slice(0, -1)
        cutAny = true
        break
      }
    }
    if (!cutAny) break
    bytes = Buffer.byteLength(JSON.stringify(state), 'utf8')
  }

  return state
}

export function decideByCode (state) {
  if (state.shape && state.shape.symbol) return null
  if (!state.shared || state.shared.length === 0) return null
  for (const s of state.shared) {
    if (s.producer_hits.length === 0 || s.consumer_hits.length === 0) return null
    const overlap = s.producer_hits.some((h) => s.consumer_hits.includes(h))
    if (overlap) return null
  }
  return 'fold'
}

export async function labelPair ({ pair, tasks, read, folds }) {
  const consumerId = pair.consumer != null ? pair.consumer : pair.b
  const consumerTask = taskById(tasks, consumerId)
  let calls = null
  if (pair.symbol) {
    calls = false
    for (const p of (consumerTask.proofTests || [])) {
      const text = await read(p)
      if (wholeWordMatch(String(text), pair.symbol)) { calls = true; break }
    }
  }
  const fold = (folds && Object.prototype.hasOwnProperty.call(folds, pair.b)) ? folds[pair.b] : null
  return { a: pair.a, b: pair.b, calls, fold }
}
